<?php
$uid = (int)$u['id']; $id = (int)($_GET['id'] ?? 0);
handle('inv_create', function () use ($uid) { $items = []; foreach ((array)($_POST['d'] ?? []) as $i => $d) $items[] = ['description' => $d, 'qty' => $_POST['q'][$i] ?? '1', 'price' => $_POST['p'][$i] ?? '']; $i = Invoices::create($uid, ['title' => $_POST['title'] ?? '', 'customer' => $_POST['customer'] ?? '', 'customer_name' => $_POST['customer_name'] ?? '', 'due' => $_POST['due'] ?? '', 'currency' => $_POST['currency'] ?? 'BDT', 'items' => $items]); flash('ok', 'Invoice created. Share the payment link or QR code.'); redirect(url('invoices', ['id' => $i])); });
handle('inv_remind', function () use ($uid) { Invoices::remind($uid, (int)$_POST['id']); return 'Reminder sent.'; });
handle('inv_cancel', function () use ($uid) { $n = q("UPDATE invoices SET status='cancelled' WHERE id=? AND issuer_id=? AND status IN ('sent','overdue')", [(int)$_POST['id'], $uid])->rowCount(); if (!$n) throw new AppError('Only unpaid invoices can be cancelled.'); return 'Invoice cancelled.'; });
if ($id) {
  $i = row('SELECT * FROM invoices WHERE id=? AND (issuer_id=? OR customer_id=?)', [$id, $uid, $uid]);
  if (!$i) { http_response_code(404); echo card('', empty_state('Invoice not found.')); return; }
  $tot = Invoices::totals($id); $items = rows('SELECT * FROM invoice_items WHERE invoice_id=?', [$id]); $pays = rows('SELECT p.*, u.name, t.ref FROM invoice_payments p JOIN users u ON u.id=p.payer_id JOIN transactions t ON t.id=p.txn_id WHERE p.invoice_id=? ORDER BY p.id', [$id]); $tl = rows("SELECT * FROM timeline_events WHERE entity_type='invoice' AND entity_id=? ORDER BY id", [$id]);
  $link = (isset($_SERVER['HTTPS']) ? 'https' : 'http') . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/') . '/' . url('pay', ['t' => $i['link_token']]);
  $ir = []; foreach ($items as $x) $ir[] = [e($x['description']), e(rtrim(rtrim($x['quantity'], '0'), '.')), mny($x['unit_price'], $i['currency']), mny(dec(cents(number_format((float)$x['quantity'] * (float)$x['unit_price'], 2, '.', ''))), $i['currency'])];
  $pr = []; foreach ($pays as $p) $pr[] = [e(fdate($p['created_at'])), e($p['name']), mny($p['amount'], $i['currency']), ref_link($p['ref'])];
  $tls = '<ul class="timeline">'; foreach ($tl as $x) $tls .= '<li><strong>' . e(ucfirst(str_replace('_', ' ', $x['event']))) . '</strong> <span class="hint">' . e(fdate($x['created_at'])) . '</span><div class="hint">' . e($x['note']) . '</div></li>'; $tls .= '</ul>';
  $mine = (int)$i['issuer_id'] === $uid;
  echo page_head($i['title'], $i['number'] . ' &middot; due ' . fdate($i['due_date'], false), '<a class="btn secondary sm" href="' . e(url('invoices')) . '">' . e(t('Back')) . '</a>') . '<div class="grid g-main"><div class="grid">' . card('Line items', tbl(['Description', 'Qty', ['Unit', 'num'], ['Total', 'num']], $ir) . '<div class="total-row"><span>Total</span><span>' . mny(dec($tot['total_c']), $i['currency']) . '</span></div><dl class="kv"><dt>Paid</dt><dd class="pos">' . mny(dec($tot['paid_c']), $i['currency']) . '</dd><dt>Outstanding</dt><dd>' . mny(dec($tot['due_c']), $i['currency']) . '</dd></dl>') . card('Payments (auto-reconciled)', tbl(['When', 'Payer', ['Amount', 'num'], 'Ref'], $pr, 'No payments yet.')) . '</div><div class="grid" style="align-content:start">' .
    card('Status', badge($i['status']) . '<p class="hint">Customer: ' . e($i['customer_name']) . '</p>' . ($mine && !in_array($i['status'], ['paid', 'cancelled'], true) ? form_start('inv_remind', 'class="inline"') . '<input type="hidden" name="id" value="' . $id . '">' . btn('Send reminder', 'secondary sm') . '</form> ' . (in_array($i['status'], ['sent', 'overdue'], true) ? form_start('inv_cancel', 'class="inline"') . '<input type="hidden" name="id" value="' . $id . '">' . btn('Cancel invoice', 'secondary sm') . '</form>' : '') : '') . (!$mine && $tot['due_c'] > 0 && !in_array($i['status'], ['cancelled', 'draft'], true) ? '<p><a class="btn" href="' . e(url('pay', ['t' => $i['link_token']])) . '">' . e(t('Pay now')) . '</a></p>' : '')) .
    ($mine ? card('Payment link and QR', '<div class="qr" data-qr="' . e($link) . '"></div><input id="lnk" value="' . e($link) . '" readonly style="margin-top:8px"><p style="margin-top:8px"><button type="button" class="btn secondary sm" data-copy="lnk">Copy link</button></p>') : '') . card('Timeline', $tls) . '</div></div>'; return;
}
$mineL = rows('SELECT i.* FROM invoices i WHERE i.issuer_id=? ORDER BY i.id DESC LIMIT 30', [$uid]); $forMe = rows('SELECT i.*, u.name issuer FROM invoices i JOIN users u ON u.id=i.issuer_id WHERE i.customer_id=? ORDER BY i.id DESC LIMIT 30', [$uid]);
$fmt = function ($l, $who) { $r = []; foreach ($l as $i) { $t = Invoices::totals((int)$i['id']); $r[] = ['<a href="' . e(url('invoices', ['id' => $i['id']])) . '"><strong>' . e($i['title']) . '</strong></a><div class="hint">' . e($i['number']) . ' &middot; ' . e($who === 'c' ? $i['customer_name'] : $i['issuer']) . '</div>', mny(dec($t['total_c']), $i['currency']), mny(dec($t['due_c']), $i['currency']), e(fdate($i['due_date'], false)), badge($i['status'])]; } return $r; };
$rowsIn = ''; for ($k = 0; $k < 3; $k++) $rowsIn .= '<div class="row"><div style="flex:3 1 160px"><input name="d[]" placeholder="Item" maxlength="150" aria-label="Item"></div><div><input name="q[]" value="1" inputmode="decimal" aria-label="Quantity"></div><div><input name="p[]" placeholder="Unit price" inputmode="decimal" aria-label="Unit price"></div></div><div style="height:6px"></div>';
echo page_head('Invoices', 'Issue invoices with payment links and QR codes. Partial payments reconcile automatically.') . '<div class="grid g-main"><div class="grid">' . card('Issued by me', tbl(['Invoice', ['Total', 'num'], ['Outstanding', 'num'], 'Due', 'Status'], $fmt($mineL, 'c'), 'You have not issued any invoices.')) . card('Addressed to me', tbl(['Invoice', ['Total', 'num'], ['Outstanding', 'num'], 'Due', 'Status'], $fmt($forMe, 'i'), 'No invoices for you.')) . '</div>' .
  card('New invoice', form_start('inv_create') . field('Title', 'title', 'text', '', 'required maxlength="150"') . field('Customer Auvryon email (optional)', 'customer', 'text', '', 'placeholder="email or phone"') . field('Customer name', 'customer_name', 'text', '', 'maxlength="100"') . '<div class="row">' . field('Due date', 'due', 'date', date('Y-m-d', strtotime('+14 days')), 'required') . select('Currency', 'currency', ['BDT' => 'BDT', 'USD' => 'USD'], 'BDT') . '</div><label>Line items</label>' . $rowsIn . btn('Create invoice') . '</form>') . '</div>';
